                logger.info(f"Merged {len(group)} duplicates for key '{key}'")
                logger.debug(f"  Kept memory {keep_id}, deleted {delete_ids}")
                logger.debug(f"  New importance: {max_importance}, merged tags: {merged_tags}")
                
